public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        String[] parts = line.split(",");
        long timestamp = Long.parseLong(parts[0]);
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
                SnapshotType type = SnapshotType.valueOf(parts[1]);
                String threadName = parts[2];
                int threadId = Integer.parseInt(parts[3]);
                long cpuTime = Long.parseLong(parts[4]);
                long userTime = Long.parseLong(parts[5]);
                long systemTime = Long.parseLong(parts[6]);
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, type, threadName, threadId, cpuTime, userTime, systemTime);
                snapshots.add(snapshot);
                break;
            }
        }
    }
    reader.close();
    return snapshots;
}
